"""Plain HTML fund pages: one document per published fund, data inlined.

**Why not a framework route.** The plan's hosting row chose plain HTML generated by
the pipeline over a route per fund, and the reason is a budget rather than a taste:
a Next route for each of 8,983 funds multiplies files and drags a React payload
onto a page that needs no JavaScript at all, against a Worker limit of 20,000 files
per version (`static-xray-frontend` §2). One document per fund, no client fetch, no
hydration — the page is complete in its first byte.

**One number, one source.** Every value here is read from the published artifact —
the same `funds/{TICKER}.json` the ledger fetches — so a fund page cannot disagree
with the ledger about a weight, a coverage figure, or an `as_of`. Nothing is
recomputed except the presentation of it, and the coverage bands are the contract's
gates (below 60% of weight covered: metrics suppressed, "not covered"; 60–70%:
"partial"), not a second opinion about them.

**What the page refuses to do.** It does not round a real position to zero, does not
renormalise as-filed weights to 100%, does not print a number without its `as_of`
and source, and does not hide a fund because its coverage is low — a low-coverage
fund gets a page that says so, in the same place a high-coverage fund says 99.4%.
"""

from __future__ import annotations

import argparse
import base64
import html
import json
import re
import sys
from dataclasses import dataclass
from pathlib import Path

from .style import Style, classify

#: Contract gates (`lookthrough-math-and-qa` §5, conventions I8). Below 60% of
#: weight covered, a concentration figure is not a fact about the fund; it is a
#: fact about our mapping, so it is withheld rather than shown small.
FULL_COVERAGE = 70.0
PARTIAL_COVERAGE = 60.0

#: Rows shown on the page. The full holdings list is the ledger's job; this is the
#: part a reader can actually use, and 25 keeps the document near 12 kB.
TOP_HOLDINGS = 25

#: Same-issuer links, so a reader can move sideways through a family of funds.
SAME_ISSUER_LINKS = 12
SIMILAR_FUND_LINKS = 12

#: A ticker becomes a directory name, so it must be a plain path segment.
SAFE_TICKER = re.compile(r"^[A-Za-z0-9._-]{1,12}$")

#: The app's own fragment grammar (`web/lib/fragment.ts`). A ticker that the ledger
#: would refuse must not be offered as a pre-filled portfolio link.
FRAGMENT_TICKER = re.compile(r"^[A-Z0-9][A-Z0-9.-]{0,9}$")

#: The canonical host. The app is noindexed until the operator promotes a release,
#: and so is this: `--indexable` exists so the decision is one flag, not an edit.
SITE = "https://unpackfund.com"

CSS_NAME = "fund-page.css"


@dataclass(frozen=True)
class Band:
    """The coverage label and whether the metrics beside it may be shown."""

    label: str
    show_metrics: bool


def coverage_band(coverage_pct: float) -> Band:
    """Coverage → the words and the gate. Boundaries are the contract's, not rounded."""
    if coverage_pct >= FULL_COVERAGE:
        return Band(f"{coverage_pct:.1f}% of weight", True)
    if coverage_pct >= PARTIAL_COVERAGE:
        return Band(f"partial — {coverage_pct:.1f}% of weight", True)
    return Band("not covered", False)


def pct(weight_bp: int) -> str:
    """Basis points to a percentage, at the one precision basis points justify."""
    return f"{weight_bp / 100:.2f}%"


def number(value: float | None, places: int) -> str:
    return "not disclosed" if value is None else f"{value:.{places}f}"


def _esc(text: str) -> str:
    return html.escape(text, quote=True)


def _holdings(fund: dict) -> list[dict]:
    """Company-exposure rows by weight, then everything else, each in file order."""
    rows = [row for row in fund.get("holdings", []) if row.get("weight_bp")]
    rows.sort(key=lambda row: (-row["weight_bp"], (row.get("name") or "").upper()))
    return rows


def render_page(
    fund: dict,
    *,
    issuer_funds: list[tuple[str, str]],
    indexable: bool = False,
    style: Style | None = None,
    similar: list[tuple[str, str]] | None = None,
) -> str:
    """One fund document → one standalone HTML page."""
    ticker = _esc(fund["ticker"])
    name = _esc(fund["name"])
    issuer = _esc(fund["issuer"])
    as_of = _esc(fund["as_of"])
    filed_at = _esc(fund["filed_at"])
    lag = fund.get("lag_days")
    source_url = _esc(fund.get("source_url") or "")
    coverage = float(fund.get("coverage_pct") or 0.0)
    band = coverage_band(coverage)
    metrics = fund.get("metrics") or {}
    rows = _holdings(fund)
    total_rows = len(rows)
    shown = rows[:TOP_HOLDINGS]
    mapped = sum(1 for row in rows if row.get("company_id"))
    unmapped_shown = sum(1 for row in shown if not row.get("company_id"))

    title = f"{fund['ticker']} holdings — what {fund['name']} owns"
    description = (
        f"{fund['ticker']} ({fund['name']}): {total_rows:,} holdings as of {fund['as_of']}, "
        f"{coverage:.1f}% of weight mapped to companies. "
        + (
            f"Largest: {shown[0]['name']} {pct(shown[0]['weight_bp'])}. "
            if shown
            else ""
        )
        + f"From SEC Form N-PORT, filed {fund['filed_at']}."
    )

    rows_html = []
    for rank, row in enumerate(shown, start=1):
        company = _esc(row.get("name") or "unknown")
        company_cell = (
            f'<a href="/c/#{_esc(row["company_id"])}">{company}</a>'
            if row.get("company_id")
            else f"{company} <span class=\"tag\">unmapped</span>"
        )
        symbol = _esc(row.get("ticker") or "")
        category = _esc(row.get("asset_cat") or "")
        # A non-equity row can outrank real companies by weight (a securities-lending
        # money-market position is often third). The type column says what it is, but
        # that column is hidden on a phone, so the label rides with the name as well.
        category_tag = (
            f' <span class="tag tag--plain">{category}</span>'
            if category and category != "equity"
            else ""
        )
        rows_html.append(
            "<tr>"
            f'<td class="num">{rank}</td>'
            f"<td>{company_cell}{category_tag}</td>"
            f'<td class="mono">{symbol or "—"}</td>'
            f'<td class="kind">{category}</td>'
            f'<td class="num">{pct(row["weight_bp"])}</td>'
            "</tr>"
        )
    holdings_html = "\n".join(rows_html)

    metrics_html = ""
    if band.show_metrics:
        metrics_html = f"""
      <dl class="metrics">
        <div><dt>Concentration (HHI)</dt><dd>{number(metrics.get("hhi"), 4)}</dd></div>
        <div><dt>Effective companies</dt><dd>{number(metrics.get("effective_n"), 1)}</dd></div>
        <div><dt>Top 10 weight</dt><dd>{number(metrics.get("top10_pct"), 2)}%</dd></div>
      </dl>"""
    else:
        metrics_html = f"""
      <p class="note">Concentration figures are withheld: only {coverage:.1f}% of this fund's
      weight maps to a company we can identify, and a concentration number computed from
      the mapped part would describe our mapping rather than the fund.</p>
      <p class="note">Low coverage is usually one of two things. Either the fund holds companies
      outside the U.S., which have no registered ticker here for us to match, or its holdings
      are filed under names that do not match an issuer we already know. The filing linked
      above is the fund&rsquo;s own and is filed with the SEC either way &mdash; the gap is in
      our mapping, not in the source.</p>"""

    similar_html = ""
    if style is not None and similar:
        links = "\n".join(
            f'<li><a href="/f/{_esc(other)}/">{_esc(other)}</a>'
            f'<span class="muted"> · {_esc(other_name)}</span></li>'
            for other, other_name in [
                pair for pair in similar if pair[0] != fund["ticker"]
            ][:SIMILAR_FUND_LINKS]
        )
        similar_html = f"""
      <section aria-labelledby="similar-heading">
        <h2 id="similar-heading">Similar {_esc(style.label)} funds</h2>
        <p class="muted">Grouped from each fund&rsquo;s own filed name, which the
        SEC&rsquo;s Names Rule requires a fund to invest 80% by, and listed with the
        funds we can see the most of first. Not a recommendation, and not a claim that
        one is better than another.</p>
        <ul class="plain">
{links}
        </ul>
      </section>"""

    issuer_html = ""
    if issuer_funds:
        links = "\n".join(
            f'<li><a href="/f/{_esc(other)}/">{_esc(other)}</a>'
            f'<span class="muted"> · {_esc(other_name)}</span></li>'
            for other, other_name in issuer_funds[:SAME_ISSUER_LINKS]
        )
        issuer_html = f"""
      <section aria-labelledby="issuer-heading">
        <h2 id="issuer-heading">More from {issuer}</h2>
        <ul class="plain">
{links}
        </ul>
      </section>"""

    ledger = ledger_link(fund["ticker"])
    ledger_action = (
        f'<a href="{_esc(ledger)}">See all {total_rows:,} holdings in the look-through ledger</a>'
        if ledger
        else '<a href="/x/">Look through a portfolio</a>'
    )

    unmapped_note = (
        f"{unmapped_shown} of the {len(shown)} companies listed here are not mapped to an "
        "issuer we can identify, so they are shown but not grouped."
        if unmapped_shown
        else ""
    )

    return f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{_esc(title)}</title>
<meta name="description" content="{_esc(description)}">
<link rel="canonical" href="{SITE}/f/{ticker}/">
{"" if indexable else '<meta name="robots" content="noindex, follow">'}
<link rel="stylesheet" href="/{CSS_NAME}">
</head>
<body>
<a class="skip-link" href="#main">Skip to content</a>
<header class="site-header">
  <div class="site-header__inner">
    <a class="wordmark" href="/">UnpackFund</a>
    <nav class="site-nav" aria-label="Sections">
      <a href="/">Builder</a>
      <a href="/x/">Ledger</a>
      <a href="/compare/">Compare</a>
      <a href="/c/">Companies</a>
      <a href="/funds/" aria-current="page">Funds</a>
    </nav>
  </div>
</header>
<main id="main">
  <p class="eyebrow">{ticker} · {issuer}</p>
  <h1>{name}</h1>
  <p class="freshness">
    Holdings as of <strong>{as_of}</strong>, filed {filed_at}
    {f"· {lag} days later" if lag is not None else ""} ·
    {f'<a href="{source_url}" rel="nofollow noopener">the fund&#39;s N-PORT filing on SEC EDGAR</a>' if source_url else "SEC N-PORT filing"}
  </p>

  <dl class="summary">
    <div><dt>Holdings</dt><dd>{total_rows:,}</dd></div>
    <div><dt>Mapped to a company</dt><dd>{mapped:,}</dd></div>
    <div><dt>Coverage</dt><dd>{band.label}</dd></div>
  </dl>{metrics_html}

  <section aria-labelledby="holdings-heading">
    <h2 id="holdings-heading">Largest holdings</h2>
    <p class="note">Showing {len(shown)} of {total_rows:,} holdings, by weight. A weight is
    this company's share of the fund, not of any portfolio.</p>
    <table>
      <caption class="visually-hidden">Largest holdings of {name}, as of {as_of}</caption>
      <thead>
        <tr><th scope="col" class="num">#</th><th scope="col">Company</th>
        <th scope="col">Ticker</th><th scope="col">Type</th>
        <th scope="col" class="num">Weight</th></tr>
      </thead>
      <tbody>
{holdings_html}
      </tbody>
    </table>
  </section>{similar_html or issuer_html}

  <section aria-labelledby="caveats-heading">
    <h2 id="caveats-heading">What this page does not tell you</h2>
    <ul class="plain">
      <li>It shows the fund, not a portfolio. To see what a mix of funds owns, open the
      <a href="/">builder</a>.</li>
      <li>{100 - coverage:.1f}% of the fund's weight is not mapped to a company we can
      identify — cash, derivatives, or issuers outside the SEC's filing system. It is
      counted, not hidden.</li>
      <li>Weights are the fund's own filing. They are not rescaled, so a fund with
      derivatives or borrowings may not add to exactly 100%.</li>
      <li>Every weight carries the filing's lag: {lag if lag is not None else "—"} days
      between the period end and the filing date. Holdings change after that date.</li>
      {f"<li>{_esc(unmapped_note)}</li>" if unmapped_note else ""}
    </ul>
  </section>

  <p class="actions">
    {ledger_action}
    <a href="/funds/">All funds</a>
    <a href="/">Build a portfolio</a>
  </p>
</main>
<footer class="site-footer">
  <p>Holdings from SEC Form N-PORT filings. Not investment advice, and not a
  recommendation of any fund. UnpackFund is not affiliated with any fund issuer.</p>
</footer>
</body>
</html>
"""


def ledger_link(ticker: str) -> str | None:
    """`/x/#v1…` with this fund at 100% — the ledger's whole-company view of it.

    The fragment is built the way the app builds it (sorted, no spaces, base64url
    without padding) so the link either decodes exactly or falls back to `/x/`.
    A single fund at 10,000 bp is a complete allocation, which is what the ledger
    requires; anything else would be refused and land on the builder.
    """
    if not FRAGMENT_TICKER.match(ticker):
        return None
    payload = json.dumps([[ticker, 10_000]], separators=(",", ":"))
    encoded = base64.urlsafe_b64encode(payload.encode()).decode().rstrip("=")
    return f"/x/#v1.{encoded}"


def _style_index(catalogue: dict[str, list]) -> dict[str, list[tuple[str, str]]]:
    """Style bucket key → funds in it, alphabetically.

    Built once for the whole release: 8,983 classifications of names, then a lookup
    per page. A fund whose name supports no bucket is simply absent, and its page
    falls back to the issuer list.
    """
    ranked: dict[str, list[tuple[tuple, str, str]]] = {}
    for ticker, row in catalogue.items():
        if not SAFE_TICKER.match(ticker):
            continue
        name, issuer = row[0], row[1] if len(row) > 1 else ""
        style = classify(name, issuer)
        if style is None:
            continue
        coverage = float(row[3]) if len(row) > 3 and row[3] is not None else 0.0
        # Alphabetical would show the same A-names forever and hide half the bucket.
        # A visitor wants a peer they can act on, so: ETFs first (the wrapper most
        # readers are looking for, read off the name like everything else here), then
        # the funds we can see the most of, then ticker for determinism. A bucket of
        # 552 therefore shows its best twelve on every page rather than a rotating
        # window: repetition across pages is the lesser cost, and the reader of one
        # page cannot see it.
        key = (0 if "ETF" in name.upper() else 1, -coverage, ticker)
        ranked.setdefault(style.key, []).append((key, ticker, name))
    index: dict[str, list[tuple[str, str]]] = {}
    for style_key, items in ranked.items():
        items.sort()
        index[style_key] = [(ticker, name) for _, ticker, name in items]
    return index


def _issuer_index(catalogue: dict[str, list]) -> dict[str, list[tuple[str, str]]]:
    by_issuer: dict[str, list[tuple[str, str]]] = {}
    for ticker, row in catalogue.items():
        if not SAFE_TICKER.match(ticker):
            continue
        by_issuer.setdefault(row[1], []).append((ticker, row[0]))
    for funds in by_issuer.values():
        funds.sort(key=lambda item: item[0])
    return by_issuer


def build(
    release_dir: Path, out_dir: Path, *, limit: int | None = None, indexable: bool = False
) -> dict:
    """Write every fund page under `out_dir`, plus the shared stylesheet."""
    catalogue_doc = json.loads((release_dir / "catalogue.json").read_text())
    catalogue: dict[str, list] = catalogue_doc["funds"]
    by_issuer = _issuer_index(catalogue)
    by_style = _style_index(catalogue)

    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / CSS_NAME).write_text(stylesheet())

    tickers = [ticker for ticker in catalogue if SAFE_TICKER.match(ticker)]
    if limit is not None:
        tickers = tickers[:limit]

    written = 0
    skipped: list[str] = []
    bytes_total = 0
    bands = {"full": 0, "partial": 0, "not-covered": 0}
    for ticker in tickers:
        fund_path = release_dir / "funds" / f"{ticker}.json"
        if not fund_path.exists():
            skipped.append(ticker)
            continue
        fund = json.loads(fund_path.read_text())
        others = [
            (other, other_name)
            for other, other_name in by_issuer.get(fund["issuer"], [])
            if other != ticker
        ]
        style = classify(fund["name"], fund.get("issuer") or "")
        page = render_page(
            fund,
            issuer_funds=others,
            indexable=indexable,
            style=style,
            similar=(
                [pair for pair in by_style.get(style.key, []) if pair[0] != ticker]
                if style is not None
                else []
            ),
        )
        target = out_dir / "f" / ticker / "index.html"
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(page)
        written += 1
        bytes_total += len(page.encode())
        coverage = float(fund.get("coverage_pct") or 0.0)
        if coverage >= FULL_COVERAGE:
            bands["full"] += 1
        elif coverage >= PARTIAL_COVERAGE:
            bands["partial"] += 1
        else:
            bands["not-covered"] += 1

    return {
        "pages": written,
        "skipped": skipped,
        "bytes": bytes_total,
        "median_bytes": bytes_total // written if written else 0,
        "bands": bands,
        "catalogue": len(catalogue),
    }


